-- Phase 4G: Gram-negative AMR organism knowledge.
insert into public.lira_knowledge_sources(organization_id,source_type,title,authority,source_url,source_version,language,status,metadata,ingestion_status)
values
(null,'guidance','About Acinetobacter','CDC','https://www.cdc.gov/acinetobacter/about/index.html','2025-06','en','review',jsonb_build_object('official',true,'topic','acinetobacter','review_required',true,'phase','4G'),'pending'),
(null,'guidance','About Pseudomonas aeruginosa','CDC','https://www.cdc.gov/pseudomonas-aeruginosa/about/index.html','2025-06','en','review',jsonb_build_object('official',true,'topic','pseudomonas-aeruginosa','review_required',true,'phase','4G'),'pending'),
(null,'surveillance','Antimicrobial resistance in the EU/EEA (EARS-Net) – Annual Epidemiological Report for 2024','ECDC','https://www.ecdc.europa.eu/en/antimicrobial-resistance/surveillance-and-disease-data','2024-data/2025-report','en','review',jsonb_build_object('official',true,'topic','amr-europe','scope','EU/EEA surveillance','review_required',true,'phase','4G'),'pending')
